import type { Metadata } from "next";

// Public origin used for canonical URLs, Open Graph and the sitemap.
// Set NEXT_PUBLIC_SITE_URL in Vercel once a custom domain is attached.
export const SITE_URL = (process.env.NEXT_PUBLIC_SITE_URL || "https://technext-3-0.vercel.app").replace(/\/+$/, "");

export const SITE_NAME = "TechNext '28";

// Every indexable route, with its sitemap priority.
export const SITE_ROUTES: { path: string; priority: number }[] = [
  { path: "/", priority: 1.0 },
  { path: "/register", priority: 0.7 },
];

// Generated by app/opengraph-image.tsx; set explicitly because a page-level openGraph
// object replaces the inherited one, image included.
const OG_IMAGE = { url: "/opengraph-image", width: 1200, height: 630, alt: SITE_NAME };

export function pageMetadata(path: string, { title, description }: { title: string; description: string }): Metadata {
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      title,
      description,
      url: path,
      siteName: SITE_NAME,
      locale: "en_US",
      type: "website",
      images: [OG_IMAGE],
    },
    twitter: {
      card: "summary_large_image",
      title,
      description,
      images: [OG_IMAGE.url],
    },
  };
}

// Portal pages (login, dashboard, admin) are private and kept out of search results.
export const portalMetadata = (title: string): Metadata => ({
  title: `${title} | ${SITE_NAME}`,
  robots: { index: false, follow: false },
});
